<script setup>const {data:items}=await useFetch('/api/content',{query:{type:'gallery'},default:()=>[]});const selected=ref(null)</script>
<template><div><div class="page-hero"><div class="wrap"><div class="breadcrumbs"><NuxtLink to="/">หน้าแรก</NuxtLink> / แกลเลอรี</div><span class="section-kicker light">OUR GALLERY</span><h1>แกลเลอรี</h1><p>ภาพบรรยากาศและเรื่องราวจากเรา</p></div></div><section class="section wrap"><div v-if="items.length" class="gallery-grid"><button v-for="item in items" :key="item.slug" @click="selected=item"><img :src="item.image" :alt="item.title"><span>{{item.title}}</span></button></div><div v-else class="empty-state">ยังไม่มีภาพที่แสดง</div></section><div v-if="selected" class="lightbox" @click.self="selected=null"><button aria-label="ปิด" @click="selected=null">×</button><img :src="selected.image" :alt="selected.title"><p>{{selected.title}}</p></div></div></template>
